import{_ as n,o as e,c as i,a4 as s,j as l}from"./chunks/framework.BRzJ4ijD.js";const u=JSON.parse('{"title":"SSA / CFG / 支配树 / dom tree","description":"","frontmatter":{},"headers":[],"relativePath":"compilers/sema/ssa.md","filePath":"compilers/sema/ssa.md","lastUpdated":1788475713000}'),p={name:"compilers/sema/ssa.md"};function o(t,a,r,c,d,h){return e(),i("div",null,[...a[0]||(a[0]=[s(`<h1 id="ssa-cfg-支配树-dom-tree" tabindex="-1">SSA / CFG / 支配树 / dom tree <a class="header-anchor" href="#ssa-cfg-支配树-dom-tree" aria-label="Permalink to &quot;SSA / CFG / 支配树 / dom tree&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>SSA (Static Single Assignment) 是现代编译器中间表示：每个变量单次赋值。CFG (Control Flow Graph) 是基本块+边，支配树 (dominator tree) 给每基本块&quot;唯一前驱节点&quot;，控制依赖 (post-dominator) 决定循环 / 分支归属。LLVM、Cranelift、V8 Turbofan、 Hotspot C2 全部走 SSA。本节走完为什么 SSA 让优化简单、dom 树算法 (Cooper-Harvey-Kennedy)、SSA 构造、φ 节点、constant folding / DCE / mem-to-reg 等基于 SSA passes。</p><hr><h2 id="一、cfg" tabindex="-1">一、CFG <a class="header-anchor" href="#一、cfg" aria-label="Permalink to &quot;一、CFG&quot;">​</a></h2><p>CFG = (basic blocks, edges)</p><ul><li>basic block: linear sequence of straight-line instructions, single entry single exit</li><li>edges: jump / fall through / branch</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>bb1: %a = 1</span></span>
<span class="line"><span>     br bb2</span></span>
<span class="line"><span></span></span>
<span class="line"><span>bb2: %cond = eq %a, 1</span></span>
<span class="line"><span>     cond_br %cond, bb3, bb4</span></span>
<span class="line"><span></span></span>
<span class="line"><span>bb3: %b = 2</span></span>
<span class="line"><span>     br bb5</span></span>
<span class="line"><span></span></span>
<span class="line"><span>bb4: %b = 3</span></span>
<span class="line"><span>     br bb5</span></span>
<span class="line"><span></span></span>
<span class="line"><span>bb5: %c = %b + 1</span></span>
<span class="line"><span>     return %c</span></span></code></pre></div><h2 id="二、ssa-形式" tabindex="-1">二、SSA 形式 <a class="header-anchor" href="#二、ssa-形式" aria-label="Permalink to &quot;二、SSA 形式&quot;">​</a></h2><p>每变量单次定义。&quot;分支合并&quot; 在汇合点用 φ (phi) function:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>bb1: %a0 = 1</span></span>
<span class="line"><span>     br bb2</span></span>
<span class="line"><span></span></span>
<span class="line"><span>bb2: %cond0 = eq %a0, 1</span></span>
<span class="line"><span>     cond_br %cond0, bb3, bb4</span></span>
<span class="line"><span></span></span>
<span class="line"><span>bb3: %b0 = 2</span></span>
<span class="line"><span>     br bb5(%b0)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>bb4: %b1 = 3</span></span>
<span class="line"><span>     br bb5(%b1)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>bb5(%bx): %c0 = %bx + 1  ← phi (%b0, %b1) chooses 收 b0 / b1</span></span>
<span class="line"><span>          return %c0</span></span></code></pre></div><p><code>phi(%b0, %b1)</code> 给 bb5 选择正确祖先版本。</p><h2 id="三、为什么-ssa" tabindex="-1">三、为什么 SSA <a class="header-anchor" href="#三、为什么-ssa" aria-label="Permalink to &quot;三、为什么 SSA&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>非 SSA:</span></span>
<span class="line"><span>  int i = 0;</span></span>
<span class="line"><span>  while (i &lt; N) { sum += a[i]; i++; }</span></span>
<span class="line"><span>  // i 在 loop 多次赋值，需要 phi 加 join，但代码没明示.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>SSA:</span></span>
<span class="line"><span>  i0 = 0</span></span>
<span class="line"><span>  loop:</span></span>
<span class="line"><span>    i_phi = phi(i0, i_succ)      ← merge values</span></span>
<span class="line"><span>    cond = i_phi &lt; N</span></span>
<span class="line"><span>    if !cond goto end</span></span>
<span class="line"><span>    sum_phi = phi(sum0, sum_succ)</span></span>
<span class="line"><span>    sum = sum_phi + a[i_phi]</span></span>
<span class="line"><span>    i_succ = i_phi + 1</span></span>
<span class="line"><span>    goto loop</span></span>
<span class="line"><span>end:</span></span>
<span class="line"><span>  return sum_phi</span></span></code></pre></div><ul><li><strong>def-use chain</strong> 显式 — 一个 SSA 变量只 one def，use 一定能反查 def</li><li><strong>常量传播更直接</strong>：value 数 declines + multiple versions</li><li><strong>DCE (Dead Code Elimination)</strong>: unused variable → entire def 可删</li><li><strong>优化自动处理 alias</strong>: 不同 def/use 易跟踪</li></ul><h2 id="四、支配树-dom-tree" tabindex="-1">四、支配树 (dom tree) <a class="header-anchor" href="#四、支配树-dom-tree" aria-label="Permalink to &quot;四、支配树 (dom tree)&quot;">​</a></h2>`,16),l("p",{起点:"","+":"",all:"",blocks:"",必经:"",b:""},"Dominator set dom(b) =",-1),s(`<ul><li>idom(b) = immediate dominator (closest strict dominator)</li><li>支配关系 form tree</li></ul><p>Cooper-Harvey-Kennedy 算法 (2001) O(n α(n,n)) — fast:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>for bb in reverse_post_order(cfg):</span></span>
<span class="line"><span>    idom[bb] = intersect(processed_preds(bb))</span></span></code></pre></div><p>支配边界 (DF(bset)): 应插 φ 的基本块集合。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>bb  has preds p1, p2</span></span>
<span class="line"><span>DF(bb) = bb ∪ DF(p1) ∪ DF(p2)   if bb has ≥2 preds</span></span></code></pre></div><p>Φ 插入算法 (Cytron 1991)：iter dominance frontier，每个 variable 算 DF ∩ definitions。</p><h2 id="五、ssa-构造算法" tabindex="-1">五、SSA 构造算法 <a class="header-anchor" href="#五、ssa-构造算法" aria-label="Permalink to &quot;五、SSA 构造算法&quot;">​</a></h2><ol><li><strong>Cytron</strong>: 计算 DF, 插 φ, 变 rename (use SSA version).</li><li><strong>PrSSA / SSI</strong>: 边插 φ 在 split edge.</li><li><strong>loop closed SSA (LCSSA)</strong>: 不让 loop value escape — 每变量 在 loop exit 插 φ.</li></ol><h2 id="六、ssa-上的优化-passes" tabindex="-1">六、SSA 上的优化 passes <a class="header-anchor" href="#六、ssa-上的优化-passes" aria-label="Permalink to &quot;六、SSA 上的优化 passes&quot;">​</a></h2><h3 id="_6-1-constant-folding" tabindex="-1">6.1 Constant folding <a class="header-anchor" href="#_6-1-constant-folding" aria-label="Permalink to &quot;6.1 Constant folding&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>%a = 1 + 2 → %a = 3</span></span></code></pre></div><h3 id="_6-2-dce-dead-code-elimination" tabindex="-1">6.2 DCE (Dead Code Elimination) <a class="header-anchor" href="#_6-2-dce-dead-code-elimination" aria-label="Permalink to &quot;6.2 DCE (Dead Code Elimination)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>%a = 1 + 2   # nobody uses %a   → 删</span></span></code></pre></div><h3 id="_6-3-common-subexpression-elimination-cse" tabindex="-1">6.3 Common Subexpression Elimination (CSE) <a class="header-anchor" href="#_6-3-common-subexpression-elimination-cse" aria-label="Permalink to &quot;6.3 Common Subexpression Elimination (CSE)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>%x = a + b</span></span>
<span class="line"><span>%y = a + b  → %y = %x</span></span></code></pre></div><h3 id="_6-4-global-value-numbering-gvn" tabindex="-1">6.4 Global Value Numbering (GVN) <a class="header-anchor" href="#_6-4-global-value-numbering-gvn" aria-label="Permalink to &quot;6.4 Global Value Numbering (GVN)&quot;">​</a></h3><p>assign 一 ID 每 equivalence class，make same expr → 同一 SSA value.</p><h3 id="_6-5-loop-invariant-code-motion-licm" tabindex="-1">6.5 Loop Invariant Code Motion (LICM) <a class="header-anchor" href="#_6-5-loop-invariant-code-motion-licm" aria-label="Permalink to &quot;6.5 Loop Invariant Code Motion (LICM)&quot;">​</a></h3><p>循环不变量出循环.</p><h3 id="_6-6-partial-redundancy-elimination-pre" tabindex="-1">6.6 Partial Redundancy Elimination (PRE) <a class="header-anchor" href="#_6-6-partial-redundancy-elimination-pre" aria-label="Permalink to &quot;6.6 Partial Redundancy Elimination (PRE)&quot;">​</a></h3><p>用 SSA + dom 树做&quot;工作量保&quot; Partial available 计算, loop-out invariant expr.</p><h3 id="_6-7-mem-to-reg" tabindex="-1">6.7 Mem-to-reg <a class="header-anchor" href="#_6-7-mem-to-reg" aria-label="Permalink to &quot;6.7 Mem-to-reg&quot;">​</a></h3><p>将 memory location 转 SSA reg (helps scalar replacement)</p><h2 id="七、ssa-destruction-out-of-ssa" tabindex="-1">七、SSA destruction (out-of-SSA) <a class="header-anchor" href="#七、ssa-destruction-out-of-ssa" aria-label="Permalink to &quot;七、SSA destruction (out-of-SSA)&quot;">​</a></h2><p>LLVM IR 是 SSA，但目标机有 register 而非 SSA. 必须移除 phi:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>phi(%x1, %x2):</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span> %x1 = ...(estimate predecessor branch)</span></span>
<span class="line"><span>Store temp sẵn in each predecessor, e.g:</span></span>
<span class="line"><span>pred1: %src1 = %x1</span></span>
<span class="line"><span>pred2: %src2 = %x2</span></span>
<span class="line"><span>join:  %dst = phi(%src1, %src2)</span></span>
<span class="line"><span>→ rewrite as:</span></span>
<span class="line"><span>pred1: %x_dst = %x1</span></span>
<span class="line"><span>pred2: %x_dst = %x2</span></span>
<span class="line"><span>join:  uses %x_dst</span></span></code></pre></div><p>Implement: &quot;critical edge splitting&quot; + 虚拟 move 移到 predecessor.</p><h2 id="八、产线误用" tabindex="-1">八、产线误用 <a class="header-anchor" href="#八、产线误用" aria-label="Permalink to &quot;八、产线误用&quot;">​</a></h2><h3 id="_8-1-phi-node-与-critical-edge" tabindex="-1">8.1 phi node 与 critical edge <a class="header-anchor" href="#_8-1-phi-node-与-critical-edge" aria-label="Permalink to &quot;8.1 phi node 与 critical edge&quot;">​</a></h3><p>Critical edge: edge from bb with multiple successors to bb with multiple preds → 必须 split 加新 bb 防 phi 安装.</p><h3 id="_8-2-mem-to-reg-只-scalar" tabindex="-1">8.2 mem-to-reg 只 scalar <a class="header-anchor" href="#_8-2-mem-to-reg-只-scalar" aria-label="Permalink to &quot;8.2 mem-to-reg 只 scalar&quot;">​</a></h3><p>array / heap object 不参与 mem-to-reg, must use Scalar Replacement of Aggregates (SROA) 的 pass.</p><h3 id="_8-3-lcssa-在-slt-边界" tabindex="-1">8.3 LCSSA 在 SLT 边界 <a class="header-anchor" href="#_8-3-lcssa-在-slt-边界" aria-label="Permalink to &quot;8.3 LCSSA 在 SLT 边界&quot;">​</a></h3><p>入门 compiler 不实现 LCSSA 也能 work, 但 LICM out-of-loop 假设 LCSSA — 大 compiler (LLVM/GCC) 默认 LCSSA.</p><h2 id="九、易错清单" tabindex="-1">九、易错清单 <a class="header-anchor" href="#九、易错清单" aria-label="Permalink to &quot;九、易错清单&quot;">​</a></h2><ol><li><strong>phi 节点</strong>：数量要与 predecessor 数匹配</li><li><strong>critical edge split</strong>: must add bogus 中间 bb</li><li>** SSA destruction** 必须正确 set/move 以保 program semantics</li><li><strong>dom tree</strong> 计算必 walk cfg in post-order / post-dominator 反之</li><li><strong>dead phi</strong> variable 不能直接删除，需要 use-def chain verify DCE</li><li><strong>Aliasing</strong> in mem-to-reg: multiple ub result name clash — 实现需要 alias analysis</li></ol><h2 id="十、这一章带走的东西" tabindex="-1">十、这一章带走的东西 <a class="header-anchor" href="#十、这一章带走的东西" aria-label="Permalink to &quot;十、这一章带走的东西&quot;">​</a></h2><ol><li>SSA: 一变量一定义，让 def-use chain 显态； phi 在合并点</li><li>CFG + dom tree 给 control flow 形式分析 / 支配边界 / branch analysis</li><li>Cytron 1991 的 SSA construction algorithm 行业基础</li><li>SSA 让 constant folding / DCE / GVN / LICM / PRE pass 写起来简单</li><li>LLVM IR 是 SSA，cranelift 亦 SSA, V8 Turbofan / Hotspot IR SSA</li><li>Phi 移除必 split critical edge + virtual moves in predecessor</li><li>LCSSA force loop var in exit phi simplifies loop optimizations</li></ol>`,38)])])}const m=n(p,[["render",o]]);export{u as __pageData,m as default};
